// The mailboxes this workflow watches (see the Gmail Trigger query), who gets the "how this
// invoice matched" email for each, and whether the email is marked read once processed.
// daniel@tigros.io is a working inbox, so its mail is left unread. Keep in step with
// INTAKE_MAILBOXES in src/lib/intake.ts.
const MAILBOXES = {
  'daniel@tigros.io': { notify: 'daniel@tigros.io', markRead: false },
  'demo+invoices@appbuilder.ai': { notify: 'daniel@tigros.io', markRead: true }
};
// Emails this workflow sends (recipient notifications, supplier requests) end with this line.
const MARKER = 'Sent by the AppBuilder.ai invoice worker';
const addrs = (h) => ((h && h.value) || []).map((v) => String(v.address || '').toLowerCase());
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const text = String(j.text || j.snippet || '');
  if ((text + String(j.html || '')).indexOf(MARKER) >= 0) continue;
  const from = (j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || (typeof j.from === 'string' ? j.from : '') || '';
  const receivedBy = addrs(j.to).concat(addrs(j.cc)).find((a) => MAILBOXES[a]) || 'daniel@tigros.io';
  const box = MAILBOXES[receivedBy];
  const o = { json: { source_message_id: 'gmail-' + j.id, gmail_id: j.id, channel: 'email', submitted_by: from, subject: j.subject || '', filename: '', text: text, received_by: receivedBy, notify_to: box.notify, mark_read: box.markRead } };
  const bin = item.binary;
  if (bin) {
    const pdfKey = Object.keys(bin).find((k) => String(bin[k].mimeType || '').indexOf('pdf') >= 0);
    if (pdfKey) {
      o.binary = { data: bin[pdfKey] };
      o.json.filename = bin[pdfKey].fileName || '';
    }
  }
  out.push(o);
}
return out;

const b = $json.body || {};
const out = { json: { source_message_id: 'app-' + b.source_id, gmail_id: '', channel: 'app', submitted_by: b.submitted_by || '', subject: '', filename: b.filename || '', text: b.text || '', received_by: '', notify_to: '', mark_read: false } };
if (b.pdf_base64) {
  const buf = Buffer.from(b.pdf_base64, 'base64');
  out.binary = { data: await this.helpers.prepareBinaryData(buf, b.filename || 'invoice.pdf', 'application/pdf') };
}
return out;

const m = $('Has PDF?').item.json;
const hasPdf = !!($('Has PDF?').item.binary && $('Has PDF?').item.binary.data);
const pdf = hasPdf ? String($json.text || ($json.pdf_text && $json.pdf_text.text) || '') : '';
const body = ((m.subject ? 'Subject: ' + m.subject + '\n' : '') + (m.text || '') + '\n' + pdf).trim().slice(0, 60000);
return { json: { source_message_id: m.source_message_id, gmail_id: m.gmail_id, channel: m.channel, submitted_by: m.submitted_by, subject: m.subject, document_text: body, received_by: m.received_by || '', notify_to: m.notify_to || '', mark_read: !!m.mark_read } };

const r = ($json.results || [])[0];
const p = r.properties || {};
return [{ json: { already_processed: true, deal_id: r.id, stage_id: p.dealstage, document_type: p.document_type, invoice_number: p.invoice_number, amount: p.amount, match_result: p.match_result, approval_level: p.approval_level, anomaly_flags: p.anomaly_flags ? String(p.anomaly_flags).split(';') : [], exception_reason: p.exception_reason || '' } }];

const ex = $('Read Document').item.json.output || {};
const list = (($('Fetch Suppliers').item.json.results) || []).map((r) => Object.assign({ id: r.id }, r.properties));
const norm = (s) => String(s || '').toLowerCase().replace(/\(demo\)/g, '').replace(/[^a-z0-9]/g, '');
const vat = norm(ex.vat_id);
let supplier = vat ? (list.find((c) => norm(c.supplier_vat_id) === vat) || null) : null;
if (!supplier && ex.supplier_name) {
  const n = norm(ex.supplier_name);
  if (n.length >= 4) {
    supplier = list.find((c) => { const m = norm(c.name); return m.length >= 4 && (m === n || m.includes(n) || n.includes(m)); }) || null;
  }
}
return [{ json: { supplier } }];

let po = null;
let lines = [];
try { const r = $('Look Up PO').item.json.results || []; po = r[0] ? Object.assign({ id: r[0].id }, r[0].properties) : null; } catch (e) { po = null; }
try { lines = ($('Get PO Lines').item.json.results || []).map((l) => Object.assign({ id: l.id }, l.properties)); } catch (e) { lines = []; }
return [{ json: { po, po_lines: lines } }];

const S = {"received":"6318170298","waiting_on_supplier":"6318170299","needs_review":"6318170300","ready_to_approve":"6318170301","approved":"6318170302","duplicate":"6318170303","rejected":"6318170304"};
const LABEL = { waiting_on_supplier: 'Waiting on supplier', needs_review: 'Needs review', ready_to_approve: 'Ready to approve', duplicate: 'Duplicate' };
const ex = $('Read Document').item.json.output || {};
const meta = $('Build Document Text').item.json;
const supplier = $('Match Supplier').item.json.supplier;
const poData = $('Collect PO').item.json;
const po = poData.po;
const poLines = poData.po_lines || [];
const history = (($('Look Up History').item.json.results) || []).map((r) => Object.assign({ id: r.id }, r.properties));
const LIMIT = 5000;
const DAY = 86400000;
const today = new Date();
today.setHours(0, 0, 0, 0);
const toDate = (s) => { if (s === undefined || s === null || s === '') return null; const d = /^\d{10,}$/.test(String(s)) ? new Date(Number(s)) : new Date(s); return isNaN(d) ? null : d; };
const normIban = (s) => String(s || '').toUpperCase().replace(/\s+/g, '');
const normText = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const docType = ['invoice', 'credit_note', 'reminder', 'question', 'other'].indexOf(ex.document_type) >= 0 ? ex.document_type : 'other';
const invDateObj = toDate(ex.invoice_date) || today;
const invDate = toDate(ex.invoice_date) ? String(ex.invoice_date).slice(0, 10) : '';
const total = Number(ex.total_amount) || 0;

const order = { ready_to_approve: 1, waiting_on_supplier: 2, needs_review: 3, duplicate: 4 };
let stage = 'ready_to_approve';
const raise = (s) => { if (order[s] > order[stage]) stage = s; };
const flags = [];
const reasons = [];
const checks = [];
const missing = [];
const fail = (flag, stg, reason, name) => { if (flag) flags.push(flag); reasons.push(reason); raise(stg); checks.push({ ok: false, name: name || flag, detail: reason }); };
const pass = (name, detail) => checks.push({ ok: true, name, detail });

const target = history.find((h) => normText(h.invoice_number) === normText(ex.invoice_number) && normText(ex.invoice_number));
const routeReminder = docType === 'reminder' && !!target;

let matchResult = '';
let lines = [];

if (docType === 'question') {
  fail(null, 'needs_review', ex.summary || 'Supplier question needs a person.', 'Supplier question');
} else if (docType === 'other') {
  fail(null, 'needs_review', 'Document is not an invoice, credit note, reminder or question.', 'Document type');
} else if (docType === 'reminder') {
  if (target) { pass('Payment reminder', 'Matched to invoice ' + ex.invoice_number + '.'); }
  else { fail(null, 'needs_review', 'Payment reminder for invoice ' + (ex.invoice_number || '(no number)') + ', which is not in the system.', 'Payment reminder'); }
} else {
  // duplicate
  const dup = history.find((h) => normText(h.invoice_number) === normText(ex.invoice_number) && normText(ex.invoice_number) && h.dealstage !== S.rejected);
  if (dup) fail('duplicate', 'duplicate', 'Invoice ' + ex.invoice_number + ' from this supplier was already received.', 'Duplicate check');
  else pass('Duplicate check', 'No earlier invoice with this number.');

  // supplier
  if (!supplier) fail('unknown_supplier', 'needs_review', 'The sender could not be matched to a known supplier.', 'Supplier');
  else if (supplier.supplier_status !== 'approved') fail('supplier_blocked', 'needs_review', 'Supplier ' + supplier.name + ' has status ' + supplier.supplier_status + ', not approved.', 'Supplier status');
  else pass('Supplier', supplier.name + ' is approved.');

  if (supplier) {
    // IBAN
    if (ex.iban && supplier.supplier_iban && normIban(ex.iban) !== normIban(supplier.supplier_iban)) {
      fail('iban_mismatch', 'needs_review', 'IBAN on the invoice differs from the one on file. Verify by phone before paying.', 'IBAN');
    } else pass('IBAN', 'Matches the IBAN on file.');
    const changed = toDate(supplier.iban_changed_on);
    if (changed) {
      const diff = (invDateObj - changed) / DAY;
      if (diff >= 0 && diff <= 30) fail('iban_recently_changed', 'needs_review', 'Supplier IBAN was changed ' + Math.round(diff) + ' days before this invoice. Confirm the change by phone.', 'IBAN change');
      else pass('IBAN change', 'No recent change.');
    }
    // certificate
    const cert = toDate(supplier.tax_certificate_valid_until);
    if (!cert || cert < today) {
      fail('certificate_expired', 'waiting_on_supplier', 'Tax-compliance certificate is ' + (cert ? 'expired' : 'missing') + '.', 'Tax certificate');
      missing.push('a current tax-compliance certificate');
    } else pass('Tax certificate', 'Valid until ' + String(supplier.tax_certificate_valid_until).slice(0, 10) + '.');
  }

  // split purchase: only invoices on the same PO count, so unrelated purchases from one supplier don't trigger it
  const samePo = normText(ex.po_number);
  const win = samePo ? history.filter((h) => normText(h.po_number) === samePo && toDate(h.invoice_date) && Math.abs((toDate(h.invoice_date) - invDateObj) / DAY) <= 14 && h.dealstage !== S.rejected && normText(h.invoice_number) !== normText(ex.invoice_number)) : [];
  const amounts = win.map((h) => Number(h.amount) || 0).concat([total]);
  const sum = amounts.reduce((a, b) => a + b, 0);
  if (win.length >= 1 && amounts.every((a) => a <= LIMIT) && sum > LIMIT) {
    fail('split_purchase', 'needs_review', amounts.length + ' invoices on ' + ex.po_number + ' within 14 days each under EUR ' + LIMIT + ' but EUR ' + sum.toFixed(2) + ' together.', 'Split purchase');
  } else pass('Split purchase', 'No pattern of invoices on this PO just under the approval limit.');

  // confidence
  const conf = [];
  const c = ex.confidence || {};
  const fieldMap = { supplier_name: ex.supplier_name, vat_id: ex.vat_id, iban: ex.iban, invoice_number: ex.invoice_number, invoice_date: ex.invoice_date, po_number: ex.po_number, total_amount: ex.total_amount };
  Object.keys(fieldMap).forEach((k) => { if (fieldMap[k] && typeof c[k] === 'number') conf.push(c[k]); });
  (ex.lines || []).forEach((l) => { if (typeof l.confidence === 'number') conf.push(l.confidence); });
  var minConf = conf.length ? Math.min.apply(null, conf) : null;
  if (minConf !== null && minConf < 0.8) fail('low_confidence', 'needs_review', 'Lowest field confidence is ' + minConf.toFixed(2) + ', below 0.80.', 'Extraction confidence');
  else pass('Extraction confidence', minConf === null ? 'No confidence data.' : 'Lowest field confidence ' + minConf.toFixed(2) + '.');

  // PO and lines
  const findPoLine = (l) => {
    const code = normText(l.item_code);
    let m = code ? (poLines.find((p) => normText(p.hs_sku) === code) || null) : null;
    if (!m) { const d = normText(l.description); if (d.length >= 4) m = poLines.find((p) => { const n = normText(p.name); return n && (n === d || n.indexOf(d) >= 0 || d.indexOf(n) >= 0); }) || null; }
    return m;
  };
  let anyOff = false;
  let anyPct = false;
  // A line reports every problem it has: line_check is a multi-select (e.g. price_off;qty_off).
  lines = (ex.lines || []).map((l) => {
    const qty = Number(l.quantity) || 0;
    const price = Number(l.unit_price) || 0;
    const issues = [];
    const notes = [];
    let pct = 0;
    let pl = null;
    if (!po) { issues.push('not_on_po'); notes.push('No purchase order to match against.'); }
    else {
      pl = findPoLine(l);
      if (!pl) { issues.push('not_on_po'); notes.push('Item ' + (l.item_code || l.description) + ' is not on PO ' + po.po_number + '.'); }
      else {
        const poPrice = Number(pl.price) || 0;
        const received = Number(pl.received_quantity) || 0;
        pct = poPrice ? (price - poPrice) / poPrice : 0;
        const pctText = (pct > 0 ? '+' : '') + (pct * 100).toFixed(1) + '%';
        if (Math.abs(pct) > 0.02) { issues.push('price_off'); notes.push('Invoiced ' + qty + ' at EUR ' + price.toFixed(2) + '; PO price EUR ' + poPrice.toFixed(2) + ' (' + pctText + ').'); }
        if (qty > received) { issues.push('qty_off'); notes.push('Invoiced ' + qty + '; only ' + received + ' received per delivery notes (ordered ' + pl.quantity + ').'); }
        if (!issues.length) notes.push(pct !== 0 ? 'Price within 2% of the PO (' + pctText + ').' : 'Matches the PO line and the delivery.');
      }
    }
    if (issues.length) anyOff = true;
    if (pct !== 0) anyPct = true;
    return { name: l.description || l.item_code || 'Line', hs_sku: l.item_code || '', quantity: qty, price: price, po_line_ref: pl ? String(pl.id) : '', line_check: issues.length ? issues.join(';') : 'matched', line_check_note: notes.join(' '), field_confidence: Number(l.confidence) || 0 };
  });

  if (!ex.po_number || !po) {
    matchResult = 'no_po';
    fail(null, 'waiting_on_supplier', ex.po_number ? 'Purchase order ' + ex.po_number + ' was not found.' : 'The invoice has no purchase order number.', 'Purchase order');
    missing.push('the purchase order number this invoice relates to');
  } else {
    pass('Purchase order', 'Found ' + po.po_number + ' (budget ' + (po.budget_code || 'n/a') + ').');
    lines.forEach((l) => {
      const iss = l.line_check.split(';');
      if (l.line_check === 'matched') { pass('Line check', l.name + ': ' + l.line_check_note); return; }
      const needsPerson = iss.indexOf('not_on_po') >= 0 || iss.indexOf('price_off') >= 0;
      fail(null, needsPerson ? 'needs_review' : 'waiting_on_supplier', l.name + ': ' + l.line_check_note, 'Line check');
      if (iss.indexOf('qty_off') >= 0) missing.push('a corrected quantity or delivery note for ' + l.name);
    });
    matchResult = anyOff ? 'mismatch' : (anyPct ? 'within_tolerance' : 'full_match');
  }
}

const approvalLevel = total <= LIMIT ? 'team_lead' : (total <= 25000 ? 'head_of_department' : 'cfo');
const stageKey = stage;
let draft = '';
if (stage === 'waiting_on_supplier' && missing.length) {
  draft = 'Dear ' + (supplier ? supplier.name : 'supplier') + ',\n\nThank you for invoice ' + (ex.invoice_number || '') + '. Before we can process it we still need:\n- ' + missing.join('\n- ') + '\n\nPlease reply to this email with the details.\n\nKind regards,\nAccounts Payable (demo)';
}
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const audit = '<p><b>Invoice worker audit</b> - result: ' + LABEL[stageKey] + '</p><ul>' + checks.map((k) => '<li>' + (k.ok ? '&#10003;' : '&#10007;') + ' ' + esc(k.name) + ': ' + esc(k.detail) + '</li>').join('') + '</ul>';

const props = {
  dealname: (ex.invoice_number || docType) + ' · ' + (supplier ? supplier.name : (ex.supplier_name || 'Unknown supplier')),
  pipeline: 'default',
  dealstage: S[stageKey === 'ready_to_approve' ? 'ready_to_approve' : stageKey],
  amount: total || '',
  document_type: docType,
  invoice_number: ex.invoice_number || '',
  invoice_date: invDate,
  due_date: toDate(ex.due_date) ? String(ex.due_date).slice(0, 10) : '',
  po_number: ex.po_number || '',
  iban_on_invoice: ex.iban || '',
  vat_amount: Number(ex.vat_amount) || '',
  match_result: matchResult,
  approval_level: (docType === 'invoice' || docType === 'credit_note') ? approvalLevel : '',
  anomaly_flags: flags.join(';'),
  exception_reason: reasons.join(' '),
  source_message_id: meta.source_message_id,
  raw_order_text: String(meta.document_text || '').slice(0, 5000),
  order_channel: meta.channel,
  min_field_confidence: typeof minConf === 'number' ? minConf : '',
  email_from: meta.channel === 'email' ? meta.submitted_by : '',
  email_subject: meta.channel === 'email' ? String(meta.subject || '').slice(0, 250) : '',
  email_received_by: meta.channel === 'email' ? meta.received_by : ''
};
Object.keys(props).forEach((k) => { if (props[k] === '' || props[k] === null || props[k] === undefined) delete props[k]; });

return [{ json: {
  stage: stageKey,
  stage_label: LABEL[stageKey],
  channel: meta.channel,
  source_id: meta.gmail_id,
  reply_to: meta.submitted_by,
  subject: meta.subject,
  route_reminder: routeReminder,
  reminder_target_deal_id: target ? target.id : null,
  supplier_id: supplier ? supplier.id : null,
  supplier_name: supplier ? supplier.name : (ex.supplier_name || ''),
  document_type: docType,
  invoice_number: ex.invoice_number || '',
  amount: total,
  match_result: matchResult,
  approval_level: props.approval_level || '',
  anomaly_flags: flags,
  exception_reason: reasons.join(' '),
  deal_properties: props,
  line_items: lines,
  audit_html: audit,
  supplier_email_draft: draft,
  notify_to: meta.channel === 'email' ? meta.notify_to : '',
  received_by: meta.received_by || '',
  mark_read: !!meta.mark_read,
  checks: checks,
  missing: missing
} }];

