parameters.jsCode:
const r = $('Apply Rules').item.json;
let dealId = null;
try { dealId = $('Create Invoice Deal').item.json.id || null; } catch (e) { dealId = null; }
if (!dealId) dealId = r.reminder_target_deal_id || null;
const out = {
  deal_id: dealId,
  stage: r.stage,
  stage_label: r.stage_label,
  document_type: r.document_type,
  supplier_name: r.supplier_name,
  invoice_number: r.invoice_number,
  amount: r.amount,
  match_result: r.match_result,
  approval_level: r.approval_level,
  anomaly_flags: r.anomaly_flags,
  exception_reason: r.exception_reason,
  lines: (r.line_items || []).map((l) => ({ name: l.name, quantity: l.quantity, price: l.price, line_check: l.line_check, line_check_note: l.line_check_note }))
};
if (r.channel === 'app' && r.supplier_email_draft) out.supplier_email_draft = r.supplier_email_draft;
return [{ json: out }];

// The email the invoice's recipient gets: the result, what to do next, every check, and a link.
// Subject and footer carry the marker the Gmail Trigger and Prepare Email use to skip it.
const r = $('Apply Rules').item.json;
const dealId = String($('Create Invoice Deal').item.json.id || '');
const APP_URL = 'https://nexxt.appbuilder.ai';
const MARKER = 'Sent by the AppBuilder.ai invoice worker';
const APPROVER = { team_lead: 'a team lead', head_of_department: 'the head of department', cfo: 'the CFO' };
const MATCH = { full_match: 'Matches the PO and the delivery notes', within_tolerance: 'Prices within the 2% tolerance of the PO', mismatch: 'Does not match the PO or the delivery notes', no_po: 'No purchase order found' };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const eur = (n) => 'EUR ' + Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const p = r.deal_properties || {};
const failed = (r.checks || []).filter((c) => !c.ok);
// Same condition as the "Send supplier email?" node that runs after this one.
const supplierEmailed = r.stage === 'waiting_on_supplier' && !!r.reply_to && !!r.supplier_email_draft;
const approver = APPROVER[r.approval_level] || '';
const missing = r.missing || [];

let headline;
let todo;
if (r.document_type === 'question' || r.document_type === 'other') {
  headline = r.document_type === 'question' ? 'A supplier question needs an answer' : 'This email is not an invoice';
  todo = failed.map((c) => c.detail).concat(['Open it in the app, answer or close it.']);
} else if (r.stage === 'ready_to_approve') {
  headline = 'Passed every check';
  todo = ['Approve it for payment in the app' + (approver ? ' (needs ' + approver + ' approval)' : '') + '.'];
} else if (r.stage === 'duplicate') {
  headline = 'Looks like a duplicate';
  todo = ['Do not pay it again: an invoice with this number from this supplier was already received.', 'Confirm and mark it as a duplicate in the app.'];
} else if (r.stage === 'waiting_on_supplier') {
  headline = 'On hold until the supplier sends what is missing';
  todo = (missing.length ? ['Missing: ' + missing.join('; ') + '.'] : failed.map((c) => c.detail))
    .concat([supplierEmailed ? 'We emailed the supplier at ' + r.reply_to + ' asking for it. Nothing to do until they reply.' : 'Ask the supplier for it, or send the invoice back from the app.']);
} else {
  headline = 'Needs a person to review it';
  todo = failed.map((c) => c.detail).concat(['Then approve, send back or reject it in the app' + (approver ? ' (payment needs ' + approver + ' approval)' : '') + '.']);
}

const label = r.invoice_number ? 'Invoice ' + r.invoice_number : (r.document_type === 'question' ? 'Supplier question' : 'Document');
const subject = 'AppBuilder invoice check: ' + r.stage_label + ' · ' + label + (r.supplier_name ? ' · ' + r.supplier_name : '');
const row = (k, v) => '<tr><td style="padding:4px 12px 4px 0;color:#666;vertical-align:top">' + esc(k) + '</td><td style="padding:4px 0">' + esc(v || '—') + '</td></tr>';
const lines = (r.line_items || []).map((l) => '<li>' + (l.line_check === 'matched' ? '&#10003; ' : '&#10007; ') + esc(l.name) + ' · ' + esc(l.quantity) + ' × ' + eur(l.price) + (l.line_check_note ? ' · ' + esc(l.line_check_note) : '') + '</li>').join('');
const link = dealId ? APP_URL + '/app/invoices/' + dealId : APP_URL + '/app/invoices';
const html = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#111;max-width:640px">'
  + '<p style="font-size:18px;margin:0 0 4px"><b>' + esc(headline) + '</b></p>'
  + '<p style="margin:0 0 16px;color:#444">' + esc(label) + (r.supplier_name ? ' from ' + esc(r.supplier_name) : '') + (r.amount ? ' · ' + eur(r.amount) : '') + ' · result: <b>' + esc(r.stage_label) + '</b></p>'
  + '<p style="margin:0"><b>What to do</b></p><ul style="margin:4px 0 16px">' + todo.map((t) => '<li>' + esc(t) + '</li>').join('') + '</ul>'
  + '<table style="border-collapse:collapse;margin-bottom:16px">'
  + row('Supplier', r.supplier_name) + row('Invoice number', r.invoice_number) + row('Amount', r.amount ? eur(r.amount) : '')
  + row('Purchase order', p.po_number) + row('Three-way match', MATCH[r.match_result] || r.match_result)
  + row('Approval', approver ? 'Needs ' + approver : '') + row('Received from', r.reply_to) + row('Sent to', r.received_by)
  + '</table>'
  + '<p style="margin:0"><b>Checks against the approval rules</b></p><ul style="margin:4px 0 16px">'
  + (r.checks || []).map((c) => '<li>' + (c.ok ? '&#10003; ' : '&#10007; ') + esc(c.name) + ': ' + esc(c.detail) + '</li>').join('') + '</ul>'
  + (lines ? '<p style="margin:0"><b>Lines</b></p><ul style="margin:4px 0 16px">' + lines + '</ul>' : '')
  + '<p><a href="' + esc(link) + '" style="display:inline-block;background:#facc15;color:#111;padding:10px 16px;text-decoration:none;font-weight:bold">Open the invoice in AppBuilder.ai</a></p>'
  + '<p style="color:#888;font-size:12px;margin-top:24px">' + MARKER + ' for ' + esc(r.received_by || r.notify_to) + '. The checks are fixed rules; the AI only reads the document.</p>'
  + '</div>';
return [{ json: { notify_to: r.notify_to, subject: subject, html: html, deal_id: dealId } }];
